/*
 * prog59_rule110.c
 *
 * Implements the original behaviour of the supplied binary.
 * The program expects two command‑line arguments:
 *
 *   1. A non‑empty binary string (only ‘0’ and ‘1’) of length ≤ 60.
 *   2. A decimal integer N (0 ≤ N ≤ 200) – the number of generations.
 *
 * It prints the initial configuration followed by N generations of the
 * elementary cellular automaton “Rule 110”.  Each generation is printed
 * on its own line as a string of ‘0’/‘1’ characters.  If any input
 * validation fails the program prints exactly the line
 *
 *     INVALID_INPUT
 *
 * (followed by a newline) and terminates.
 *
 * The implementation follows the logic that was recovered from the
 * decompiled, heavily‑obfuscated binary, but it is written in clean,
 * idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN   60   /* maximum length of the initial pattern   */
#define MAX_STEPS 200  /* maximum number of generations to produce */

/* Rule 110 table: index = (left<<2) | (center<<1) | right */
static const int RULE110[8] = {
    0, /* 000 */
    1, /* 001 */
    1, /* 010 */
    1, /* 011 */
    0, /* 100 */
    1, /* 101 */
    1, /* 110 */
    0  /* 111 */
};

/* Helper: print the error message used by the original binary */
static void invalid_input(void) {
    puts("INVALID_INPUT");
}

/* Validate that a string consists only of ‘0’ and ‘1’. */
static int is_binary_string(const char *s) {
    while (*s) {
        if (*s != '0' && *s != '1')
            return 0;
        ++s;
    }
    return 1;
}

/* Compute the next generation using Rule 110 with zero padding at the ends. */
static void next_generation(const char *prev, char *next, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        int left   = (i == 0)     ? 0 : (prev[i - 1] - '0');
        int center = prev[i] - '0';
        int right  = (i + 1 == len) ? 0 : (prev[i + 1] - '0');

        int idx = (left << 2) | (center << 1) | right;
        next[i] = (char)(RULE110[idx] + '0');
    }
}

/* ---------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* --------------------------------------------------------------
       Argument count check – the original binary required exactly 3
       arguments (program name + 2 user arguments).  Anything else is
       considered invalid.
       -------------------------------------------------------------- */
    if (argc < 3) {
        invalid_input();
        return 0;
    }

    /* --------------------------------------------------------------
       1st argument: initial pattern
       -------------------------------------------------------------- */
    const char *init = argv[1];
    size_t len = strlen(init);

    if (len == 0 || len > MAX_LEN || !is_binary_string(init)) {
        invalid_input();
        return 0;
    }

    /* --------------------------------------------------------------
       2nd argument: number of generations (steps)
       -------------------------------------------------------------- */
    char *endptr;
    long steps = strtol(argv[2], &endptr, 10);

    if (endptr == argv[2] || *endptr != '\0') {   /* not a number */
        invalid_input();
        return 0;
    }
    if (steps < 0) {
        invalid_input();
        return 0;
    }
    if (steps > MAX_STEPS)
        steps = MAX_STEPS;        /* the original program caps at 200 */

    /* --------------------------------------------------------------
       Allocate two buffers for the current and next rows.
       The original binary used a static 2‑D array of size 60×60,
       but we only need two rows at a time.
       -------------------------------------------------------------- */
    char cur[MAX_LEN + 1];
    char nxt[MAX_LEN + 1];
    memcpy(cur, init, len);
    cur[len] = '\0';

    /* --------------------------------------------------------------
       Print the initial configuration.
       -------------------------------------------------------------- */
    puts(cur);

    /* --------------------------------------------------------------
       Generate and print each subsequent generation.
       -------------------------------------------------------------- */
    for (long gen = 0; gen < steps; ++gen) {
        next_generation(cur, nxt, len);
        nxt[len] = '\0';
        puts(nxt);
        memcpy(cur, nxt, len);
    }

    return 0;
}
